INSERT INTO cfg_unit (unit_cfg_id, code, name, tier, stats) VALUES (1, 'infantry', '步兵', 1, '{"atk":10,"def":15,"hp":100,"speed":50,"food_upkeep":1,"troop_type":"infantry","counter":{"advantage":1.25,"disadvantage":0.8,"neutral":1.0},"counter_edges":[["cavalry","infantry"],["infantry","archer"],["archer","cavalry"]]}') ON CONFLICT (unit_cfg_id) DO UPDATE SET code = EXCLUDED.code, name = EXCLUDED.name, tier = EXCLUDED.tier, stats = EXCLUDED.stats;
